// One-off: v1 images -> v2 source layout (assets/images/source). Run: node scripts/migrate-v1-images.mjs [v1Dir]
import fs from 'node:fs';
import crypto from 'node:crypto';

const v1 = process.argv[2] ?? '../assets_v1';
const src = 'assets/images/source';
const sha = (f) => crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');

// v1 file -> v2 path (masters only: light/dark/currentColor variants and PNG sizes are generated by the build)
const LOGOS = {
  'base.svg': 'jjjei/mark.svg',
  'jjjei_stacked.svg': 'jjjei/stacked.svg',
  'jjjei_stacked-fit.svg': 'jjjei/stacked-fit.svg',
  'jjjei_horizontal.svg': 'jjjei/horizontal.svg',
  'jjjei_horizontal-50yrs.png': 'jjjei/horizontal-50yrs.png', // raster only in v1, no SVG master exists
  'marymart_horizontal.svg': 'marymart/horizontal.svg',
  'marymart_stacked.svg': 'marymart/stacked.svg',
};
const mapping = {};
for (const [from, to] of Object.entries(LOGOS)) { fs.copyFileSync(`${v1}/images/logo/${from}`, `${src}/logos/${to}`); mapping[`images/logo/${from}`] = `images/logos/${to}`; }
// v1 files that are derived or duplicate: record where they went so the migration guide can say so
const base = sha(`${v1}/images/logo/base.svg`);
const logoSvg = sha(`${v1}/images/logo/logo.svg`);
mapping['images/logo/logo.svg'] = logoSvg === base ? 'images/logos/jjjei/mark.svg (byte-identical duplicate of base.svg)' : 'UNMAPPED';
for (const f of fs.readdirSync(`${v1}/images/logo`)) {
  if (mapping[`images/logo/${f}`]) continue;
  const m = f.match(/^(.*?)-(light|dark)\.(svg|png)$/); // base-light.svg -> jjjei/mark-light.svg ...
  const stem = m ? m[1] : f.replace(/\.(svg|png)$/, '');
  const target = Object.entries(LOGOS).find(([k]) => k.replace(/\.(svg|png)$/, '') === stem)?.[1];
  mapping[`images/logo/${f}`] = target
    ? `images/logos/${target.replace(/\.svg$/, '')}${m ? '-' + m[2] : ''}.${f.endsWith('.png') ? 'png (generated sizes: name@<width>.png)' : 'svg'}`
    : 'UNMAPPED';
}

for (const f of fs.readdirSync(`${v1}/images/misc/background-pattern`)) {
  fs.copyFileSync(`${v1}/images/misc/background-pattern/${f}`, `${src}/patterns/${f}`);
  mapping[`images/misc/background-pattern/${f}`] = `images/patterns/${f}`;
}
// v1's grid/dots patterns were data-URIs in config/backgroundPatterns.json: make them files like the others
const pats = JSON.parse(fs.readFileSync(`${v1}/config/backgroundPatterns.json`, 'utf8'));
const settings = {};
for (const [name, p] of Object.entries(pats)) {
  fs.writeFileSync(`${src}/patterns/${name}.svg`, decodeURIComponent(p.svg.replace(/^data:image\/svg\+xml,/, '')) + '\n');
  settings[name] = { 'background-size': p['background-size'], 'background-repeat': p['background-repeat'] };
  mapping[`config/backgroundPatterns.json#${name}`] = `images/patterns/${name}.svg`;
}
fs.writeFileSync('tokens/patterns.json', JSON.stringify(settings, null, 2) + '\n'); // only display settings now; the artwork is the .svg
fs.writeFileSync(`${src}/v1-mapping.json`, JSON.stringify(mapping, null, 2) + '\n');
console.log(`${Object.keys(mapping).length} v1 paths mapped; unmapped:`, Object.entries(mapping).filter(([, v]) => v === 'UNMAPPED').map(([k]) => k));
